  <script>
    // ── CAROUSEL ──────────────────────────────────────────────────────────────
    (function () {
      const track = document.getElementById('carouselTrack');
      const prevBtn = document.getElementById('carouselPrev');
      const nextBtn = document.getElementById('carouselNext');
      const dotsContainer = document.getElementById('carouselDots');

      let currentIndex = 0;

      function getVisibleCount() {
        const w = window.innerWidth;
        if (w <= 480) return 1;
        if (w <= 768) return 2;
        if (w <= 1024) return 3;
        return 4;
      }

      const cards = Array.from(track.children);
      const totalCards = cards.length;

      function getTotalSlides() {
        return Math.ceil(totalCards / getVisibleCount());
      }

      function buildDots() {
        dotsContainer.innerHTML = '';
        const slides = getTotalSlides();
        for (let i = 0; i < slides; i++) {
          const dot = document.createElement('button');
          dot.className = 'carousel-dot' + (i === currentIndex ? ' active' : '');
          dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
          dot.addEventListener('click', () => goTo(i));
          dotsContainer.appendChild(dot);
        }
      }

      function updateDots() {
        const dots = dotsContainer.querySelectorAll('.carousel-dot');
        dots.forEach((d, i) => d.classList.toggle('active', i === currentIndex));
      }

      function goTo(index) {
        const slides = getTotalSlides();
        currentIndex = Math.max(0, Math.min(index, slides - 1));
        const visCount = getVisibleCount();
        const gap = 20;
        const cardWidth = track.parentElement.offsetWidth / visCount - (gap * (visCount - 1) / visCount);
        const offset = currentIndex * visCount * (cardWidth + gap);
        track.style.transform = `translateX(-${offset}px)`;
        prevBtn.disabled = currentIndex === 0;
        nextBtn.disabled = currentIndex >= slides - 1;
        updateDots();
      }

      prevBtn.addEventListener('click', () => goTo(currentIndex - 1));
      nextBtn.addEventListener('click', () => goTo(currentIndex + 1));

      window.addEventListener('resize', () => {
        currentIndex = 0;
        buildDots();
        goTo(0);
      });

      buildDots();
      goTo(0);
    })();

    // ── STORE LOCATOR ─────────────────────────────────────────────────────────
    (function () {
      const btn = document.getElementById('storeSearchBtn');
      const input = document.getElementById('zipInput');
      const results = document.getElementById('locatorResults');

      function doSearch() {
        const val = input.value.trim();
        if (!val) {
          input.focus();
          input.style.borderColor = 'var(--orange-dark)';
          setTimeout(() => input.style.borderColor = '', 1200);
          return;
        }
        results.classList.add('visible');
        results.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }

      btn.addEventListener('click', doSearch);
      input.addEventListener('keydown', (e) => { if (e.key === 'Enter') doSearch(); });
    })();

    // ── NEWSLETTER ────────────────────────────────────────────────────────────
    (function () {
      const btn = document.getElementById('subscribeBtn');
      const input = document.getElementById('emailInput');
      const confirm = document.getElementById('newsletterConfirm');

      btn.addEventListener('click', () => {
        const val = input.value.trim();
        if (!val || !val.includes('@')) {
          input.style.borderColor = 'var(--orange-dark)';
          input.focus();
          setTimeout(() => input.style.borderColor = '', 1400);
          return;
        }
        input.value = '';
        confirm.classList.add('visible');
        btn.disabled = true;
        btn.textContent = 'Subscribed!';
      });

      input.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') btn.click();
      });
    })();
  </script>
